CREATE DATABASE RaceDayDB;
GO
USE RaceDayDB;
CREATE TABLE Users (UserId INT IDENTITY PRIMARY KEY, FirstName NVARCHAR(100), LastName NVARCHAR(100), Email NVARCHAR(200) UNIQUE, PasswordHash NVARCHAR(500), Role NVARCHAR(20), Phone NVARCHAR(20));
CREATE TABLE Categories (CategoryId INT IDENTITY PRIMARY KEY, Name NVARCHAR(50), Description NVARCHAR(200));
CREATE TABLE Events (EventId INT IDENTITY PRIMARY KEY, Title NVARCHAR(200), Description NVARCHAR(1000), EventDate DATETIME, Location NVARCHAR(200), EventType NVARCHAR(20), BannerImageUrl NVARCHAR(500), OrganiserId INT, CategoryId INT FOREIGN KEY REFERENCES Categories(CategoryId));
CREATE TABLE Enrolments (EnrolmentId INT IDENTITY PRIMARY KEY, UserId INT FOREIGN KEY REFERENCES Users(UserId), EventId INT FOREIGN KEY REFERENCES Events(EventId), CategoryId INT, Status NVARCHAR(20), EnrolledDate DATETIME);
CREATE TABLE Results (ResultId INT IDENTITY PRIMARY KEY, EnrolmentId INT FOREIGN KEY REFERENCES Enrolments(EnrolmentId), FinishTime TIME, Position INT, TotalFinishers INT);
